import React from 'react';
import styled from 'styled-components';
import SectionTitle from '../components/SectionTitle';
import Button from '../components/Button';

const AboutContainer = styled.section`
  padding: 5rem 0;

  @media (max-width: 768px) {
    padding: 3rem 0;
  }
`;

const ContentWrapper = styled.div`
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  max-width: 800px;
  margin: 0 auto;
`;

const Subtitle = styled.h3`
  font-size: 1.5rem;
  margin-bottom: 1.5rem;
  color: ${props => props.theme.fourthColor};

  @media (max-width: 768px) {
    font-size: 1.25rem;
  }
`;

const Description = styled.p`
  line-height: 1.8;
  margin-bottom: 2rem;
  font-size: 1.1rem;
  color: ${props => props.theme.fourthColor};
  white-space: pre-line;
  text-align: justify;

  @media (max-width: 768px) {
    font-size: 1rem;
    text-align: center;
  }
`;

const ButtonContainer = styled.div`
  margin-top: 1rem;
`;

const AboutPage = ({ strings, uriHandler }) => {
  return (
    <AboutContainer id="about">
      <SectionTitle>{strings.aboutMeTitle}</SectionTitle>
      <ContentWrapper>
        <Subtitle>{strings.getToKnowMe}</Subtitle>
        <Description>{strings.aboutMe}</Description>
        <ButtonContainer>
          <Button onClick={() => uriHandler.openUri('/CV.pdf')}>
            {strings.downLoadResume}
          </Button>
        </ButtonContainer>
      </ContentWrapper>
    </AboutContainer>
  );
};

export default AboutPage;
